import sys
import types

NS = types.SimpleNamespace
TAGGER_PROMPT = "Tag the ticket as billing, technical or account. Reply with the tag only."
_THINKING = {"low": 40, "medium": 160, "high": 900, "xhigh": 2400, "max": 6000}


def load_cases(path):
    return [{"text": "Charged twice for order #5521", "tag": "billing"},
            {"text": "The app crashes when I log in", "tag": "technical"},
            {"text": "Please change my email address", "tag": "account"}]


def _create(*, model, max_tokens, messages, system=None, output_config=None, **kwargs):
    effort = (output_config or {}).get("effort", "medium")
    text = messages[-1]["content"].lower()
    tag = ("billing" if "charged" in text else
           "account" if "email" in text else "technical")
    thinking = _THINKING[effort]
    usage = NS(input_tokens=180, output_tokens=thinking + 2,
               output_tokens_details=NS(thinking_tokens=thinking))
    content = [NS(type="thinking", thinking=""), NS(type="text", text=tag)]
    return NS(content=content, stop_reason="end_turn", usage=usage)


class _Anthropic:
    def __init__(self, **kwargs):
        self.messages = NS(create=_create)


sys.modules["anthropic"] = NS(Anthropic=_Anthropic)
